def format_id_grouped(n, width, group):
    padded = str(n).zfill(width)
    def build(remaining):
        if len(remaining) <= group:
            return [remaining]
        return [remaining[:group]] + build(remaining[group:])
    return '-'.join(build(padded))

def count_words_case_insensitive(text):
    words = [w.lower() for w in text.split()]
