def group_by_last_char(strings):
    ordered = sorted(strings, key=lambda s: (s[-1], s))
    grouped = groupby(ordered, key=lambda s: s[-1])
    return {ch: list(grp) for ch, grp in grouped}

def count_by_sign(nums):
    positive = sum(1 for x in nums if x > 0)
    negative = sum(1 for x in nums if x < 0)
