def smart_truncate(s, maxlen):
    if len(s) <= maxlen:
        return s
    limit = maxlen - 3
    if limit <= 0:
        return s[:maxlen]
    window = s[:limit]
    head, _, _ = window.rpartition(' ')
    return (head if head else window) + '...'

