def symmetric_difference_preserve_order(a, b):
    from itertools import chain
    a_set, b_set = set(a), set(b)
    candidates = [x for x in chain(a, b) if (x in a_set) != (x in b_set)]
    return list(dict.fromkeys(candidates))

def count_distinct_prime_factors(n):
    def smallest_factor(x):
        if x % 2 == 0:
            return 2
        f = 3
        while f * f <= x:
            if x % f == 0:
                return f
            f += 2
        return x
    count = 0
    remaining = n
    while remaining > 1:
        f = smallest_factor(remaining)
        count += 1
        while remaining % f == 0:
            remaining //= f
    return count

def is_near_palindrome(s):
    def check(i, j, skipped):
        while i < j:
            if s[i] == s[j]:
                i += 1
                j -= 1
            elif not skipped:
                return check(i + 1, j, True) or check(i, j - 1, True)
            else:
                return False
        return True
    return check(0, len(s) - 1, False)

